/**
 * @param {string} s
 * @return {number}
 */
var minInsertions = function(s) {
    let open = 0;
    let closed = 0;
    let missing = 0;

    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            open++;
            continue;
        }

        if (open > 0) {
            open--;
        } else {
            closed++;
        }

        if (s[i + 1] === ')') {
            i++;
        } else {
            missing++;
        }
    }

    return open * 2 + closed + missing;
};
